-- =============================================================================
-- TIMELINE SEED 2 — refinement pass. Adds ~200 entries across cosmos, earth,
-- life, humans, civilizations, science, technology, art, culture, migration,
-- invention, exploration and ideas; hidden discoveries; companion lines;
-- categories and honest uncertainty for existing rows. Runs after 01-timeline.sql.
-- Dates: negative = BCE as written; deep time = negative years.
-- =============================================================================

-- ---------------------------------------------------------------- categories + uncertainty for existing entries
update public.timeline_entries set category = 'cosmos' where slug in ('universe','big-bang','first-stars','milky-way','sun-forms');
update public.timeline_entries set category = 'earth' where slug in ('earth','hadean','archean','proterozoic','earth-forms','moon-forms','oceans-form','great-oxidation','ice-age-ends','coal-forests','grasslands');
update public.timeline_entries set category = 'life' where kind in ('organism','extinction') or slug in ('life','complex-life','dinosaurs','mammals','paleozoic','mesozoic','cenozoic','cambrian','ordovician','silurian','devonian','carboniferous','permian','triassic','jurassic','cretaceous','paleogene','neogene','quaternary','first-life','cambrian-explosion');
update public.timeline_entries set category = 'humans' where slug in ('humans','paleolithic','lucy','homo-erectus','neanderthals','homo-sapiens','control-of-fire','first-stone-tools','dogs-domesticated');
update public.timeline_entries set category = 'migration' where slug in ('out-of-africa','australia-settled','americas-settled','polynesia-hawaii','aotearoa-settled');
update public.timeline_entries set category = 'exploration' where slug in ('silk-road','vikings','zheng-he','columbus','alexander','moon-landing','sputnik');
update public.timeline_entries set category = 'civilizations' where kind = 'civilization' or slug in ('civilizations','bronze-age','iron-age','classical','post-classical','early-modern','industrial','contemporary','modern-world','neolithic','uruk','egypt-unified','qin-unification','fall-of-rome','constantinople-1453','bronze-age-collapse','black-death','ww1','ww2','united-nations','india-independence','mandela','berlin-wall','us-independence','french-revolution','haitian-revolution','nz-womens-vote');
update public.timeline_entries set category = 'science' where slug in ('copernicus','galileo-telescope','newton','darwin','vaccination','penicillin','dna','house-of-wisdom','gupta');
update public.timeline_entries set category = 'invention' where slug in ('wheel','writing','alphabet','pottery','farming-begins','paper','gunpowder','movable-type','gutenberg','steam-engine','railway','telegraph','telephone','light-bulb','first-car','first-flight','photography');
update public.timeline_entries set category = 'technology' where slug in ('personal-computer','world-wide-web','smartphone','wikipedia');
update public.timeline_entries set category = 'art' where slug in ('cave-art','terracotta-army','nazca-lines','angkor-wat','taj-mahal','leonardo','shakespeare','great-pyramid','stonehenge','gobekli-tepe');
update public.timeline_entries set category = 'ideas' where slug in ('athens-democracy','buddha','confucius','magna-carta','jesus','muhammad','hammurabi','olympics');
update public.timeline_entries set category = 'history' where slug in ('today');

-- Deep time is known to within a few percent; farming-era dates to a few centuries.
update public.timeline_entries set start_uncertainty = abs(start_year) * 0.04 where precision = 'deep' and start_uncertainty is null and abs(start_year) > 20000;
update public.timeline_entries set start_uncertainty = abs(start_year) * 0.1 where precision = 'deep' and start_uncertainty is null;
update public.timeline_entries set start_uncertainty = 300 where precision = 'approx' and start_uncertainty is null;
update public.timeline_entries set start_uncertainty = 50 where precision = 'century' and start_uncertainty is null;
update public.timeline_entries set date_label = 'c. 9700–3500 BCE' where slug = 'neolithic';
update public.timeline_entries set date_label = 'c. 300,000 years ago' where slug = 'homo-sapiens';
update public.timeline_entries set date_label = 'c. 3.3 million to 12,000 years ago' where slug = 'paleolithic';

-- Companion lines for the entries children open most.
update public.timeline_entries set companion_line = c.line from (values
  ('big-bang','Everything. All at once. I need a snack.'),
  ('t-rex','I am NOT going in there.'),
  ('asteroid-impact','Bad day for the dinosaurs. Good day for us, eventually.'),
  ('homo-sapiens','Hello, us!'),
  ('first-dinosaurs','Small. Fast. Very, very old.'),
  ('lucy','She walked on two legs before anyone had big ideas.'),
  ('farming-begins','Wheat! Bread! Neighbours!'),
  ('writing','Someone wrote something down and it is STILL here.'),
  ('great-pyramid','Made of 2.3 million blocks. I counted four.'),
  ('magna-carta','A king had to follow rules. Imagine.'),
  ('mongol-empire','They rode from Korea to Hungary. On horses.'),
  ('columbus','Two worlds meet. Everything changes, not all of it good.'),
  ('moon-landing','Footprints. On the Moon. Still there.'),
  ('today','This is you. Everything else came first.')
) as c(slug, line) where public.timeline_entries.slug = c.slug;

-- ---------------------------------------------------------------- new entries
create temp table seed2 (
  slug text, kind text, category text, name text, tagline text, start_year double precision, end_year double precision, is_ongoing boolean,
  precision text, start_unc double precision, end_unc double precision, date_label text, parent_slug text, level int, region_slug text, lat numeric, lng numeric,
  importance int, age_band int, curiosity_key text, what text, where_text text, why text, color_hex text, icon_key text, is_hidden boolean, companion_line text
);

insert into seed2 values
-- ===== COSMOS =====
('cmb','event','cosmos','Light Fills the Universe','The universe becomes see-through.',-13799620000,null,false,'deep',1e7,null,'380,000 years after the Big Bang',null,0,'cosmos',null,null,2,3,'wonder','The hot fog of the early universe clears and light travels freely for the first time. We still detect that glow today.','Everywhere.','It is the oldest light we can see, a baby picture of the universe.','#b7a9d6','star',false,null),
('first-galaxies','event','cosmos','The First Galaxies','Stars gather into cities of light.',-13400000000,null,false,'deep',2e8,null,null,null,0,'cosmos',null,null,2,2,'wonder','Gravity pulls the first stars into small galaxies that merge and grow.','Everywhere.','Galaxies are where stars, planets and eventually life are made.','#8e8bc2','galaxy',false,null),
-- ===== EARTH =====
('late-heavy-bombardment','event','earth','The Great Bombardment','Rocks rain from the sky for 300 million years.',-4100000000,-3800000000,false,'deep',1e8,1e8,null,null,0,'earth',null,null,1,3,'wonder','Leftover debris from building the planets crashes into Earth and the Moon. Many of the Moon''s craters date from this time.','Earth and the Moon.','Life may have begun as soon as the bombardment calmed.','#7a635a','comet',false,null),
('stromatolites','organism','life','Stromatolites','Living rocks built by microbes.',-3500000000,null,false,'deep',1e8,null,null,null,0,'oceania',-26,114,2,2,'sprout','Mats of microbes trap sand into layered mounds. Some still grow today in Shark Bay, Australia.','Shallow seas; today, Western Australia.','Some of the oldest evidence of life on Earth.','#8fae8b','mound',false,'Rocks that are alive. Slowly.'),
('snowball-earth','event','earth','Snowball Earth','Ice reaches the equator.',-720000000,-635000000,false,'deep',1e7,1e7,null,null,0,'earth',null,null,2,3,'wonder','The whole planet freezes over, possibly more than once, before volcanoes warm it again.','Earth.','Complex animal life appears soon after the thaw.','#b9c9db','snow',false,null),
('ordovician-extinction','extinction','life','The Ordovician Extinction','The seas empty.',-444000000,null,false,'deep',2e6,null,null,null,0,'earth',null,null,2,3,'fossil','Ice and falling sea levels wipe out most ocean species.','Oceans.','The first of the five great extinctions.','#7e9bc2','skull',false,null),
('devonian-extinction','extinction','life','The Devonian Extinction','Reefs collapse.',-372000000,null,false,'deep',5e6,null,null,null,0,'earth',null,null,1,3,'fossil','Oxygen drains from the oceans and reef-building animals die out.','Oceans.','Sharks and land animals come through it.','#7e9bc2','skull',false,null),
('pangaea-forms','event','earth','Pangaea Forms','All the land in one piece.',-335000000,null,false,'deep',1e7,null,null,null,0,'earth',null,null,2,2,'wonder','The continents drift together into a single supercontinent.','Earth.','You could have walked from Africa to Antarctica.','#c98a4b','mountain',false,null),
('triassic-extinction','extinction','life','The Triassic Extinction','Room for the dinosaurs to grow.',-201000000,null,false,'deep',2e6,null,null,null,0,'earth',null,null,2,3,'fossil','Massive volcanoes as Pangaea begins to split wipe out many rivals of the early dinosaurs.','Earth.','After this, dinosaurs rule.','#7fa36b','skull',false,null),
('pangaea-breaks','event','earth','Pangaea Breaks Apart','The Atlantic opens.',-175000000,null,false,'deep',1e7,null,null,null,0,'earth',null,null,2,2,'wonder','The supercontinent splits and the Atlantic Ocean begins to open.','Earth.','This is why South America and Africa look like puzzle pieces.','#9fc6e0','wave',false,null),
('himalayas-rise','event','earth','The Himalayas Rise','India crashes into Asia.',-50000000,null,false,'deep',5e6,null,null,null,0,'south-asia',28,86,2,3,'wonder','India collides with Asia and pushes up the highest mountains on Earth. They are still rising.','South Asia.','Mountains are not forever; they are just slow.','#c98a4b','mountain',false,null),
('panama-isthmus','event','earth','The Americas Join','A land bridge closes the ocean gap.',-2800000,null,false,'deep',3e5,null,null,null,0,'mesoamerica',9,-80,1,3,'wonder','Volcanic land rises to connect North and South America, and animals cross both ways.','Panama.','It also changed ocean currents, and perhaps the climate.','#7fa36b','mountain',false,null),
('ice-ages-begin','event','earth','The Ice Ages Begin','Ice comes and goes, for 2.6 million years.',-2600000,null,false,'deep',1e5,null,null,null,0,'earth',null,null,2,2,'wonder','Earth enters a long cycle of cold ice ages and warm spells. We are in a warm spell now.','Earth.','Humans evolved during the ice ages.','#b9c9db','snow',false,null),
('toba-eruption','event','earth','The Toba Supereruption','The biggest volcano in human times.',-72000,null,false,'deep',3000,null,null,null,0,'southeast-asia',2,99,1,4,'wonder','A supervolcano in Sumatra darkens skies worldwide for years.','Sumatra, Indonesia.','Some scientists think it nearly wiped out early humans.','#7a635a','fire',false,null),
('younger-dryas','event','earth','The Big Freeze','A sudden return to cold, then the thaw.',-10900,-9700,false,'approx',200,100,'c. 10,900–9,700 BCE',null,0,'earth',null,null,1,4,'wonder','Just as the ice age was ending, the climate flipped back to cold for a thousand years.','Northern hemisphere.','When it ended, farming began.','#b9c9db','snow',false,null),
