insert into public.timeline_entries
  (slug, kind, category, name, tagline, start_year, end_year, is_ongoing, precision, start_uncertainty, end_uncertainty, date_label, level, region_slug, lat, lng, importance, age_band, curiosity_key, what, where_text, why, color_hex, icon_key, is_hidden, companion_line, status)
select slug, kind::public.timeline_kind, category, name, tagline, start_year, end_year, is_ongoing, precision, start_unc, end_unc, date_label, level, region_slug, lat, lng, importance, age_band, curiosity_key, what, where_text, why, color_hex, icon_key, is_hidden, companion_line, 'active'
from seed2
on conflict (slug) do update set
  kind = excluded.kind, category = excluded.category, name = excluded.name, tagline = excluded.tagline, start_year = excluded.start_year, end_year = excluded.end_year,
  is_ongoing = excluded.is_ongoing, precision = excluded.precision, start_uncertainty = excluded.start_uncertainty, end_uncertainty = excluded.end_uncertainty,
  date_label = excluded.date_label, region_slug = excluded.region_slug, lat = excluded.lat, lng = excluded.lng, importance = excluded.importance,
  age_band = excluded.age_band, curiosity_key = excluded.curiosity_key, what = excluded.what, where_text = excluded.where_text, why = excluded.why,
  color_hex = excluded.color_hex, icon_key = excluded.icon_key, is_hidden = excluded.is_hidden, companion_line = excluded.companion_line, status = 'active';

drop table if exists seed2;

